HEADER = """<?xml version="1.0" encoding="utf-8"?>
<root>
  <resheader name="resmimetype"><value>text/microsoft-resx</value></resheader>
  <resheader name="version"><value>2.0</value></resheader>
  <resheader name="reader"><value>System.Resources.ResXResourceReader, System.Windows.Forms, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089</value></resheader>
  <resheader name="writer"><value>System.Resources.ResXResourceWriter, System.Windows.Forms, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089</value></resheader>
"""

# a repeated key in T silently replaces the first one (and its text on another page)
import re
with open(os.path.abspath(__file__), encoding="utf-8") as source:
    keys = re.findall(r'^"(\w+)":', source.read(), re.MULTILINE)
repeated = sorted({key for key in keys if keys.count(key) > 1})
assert not repeated, f"keys defined twice: {repeated}"

out_dir = sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "src", "Vizstrap", "Localization")
os.makedirs(out_dir, exist_ok=True)

for i, lang in enumerate(LANGS):
    name = "Strings.resx" if lang == "en" else f"Strings.{lang}.resx"
    lines = [HEADER]
    for key, values in T.items():
        assert len(values) == len(LANGS), key
        lines.append(f'  <data name="{key}" xml:space="preserve"><value>{escape(values[i])}</value></data>\n')
    lines.append("</root>\n")
    with open(os.path.join(out_dir, name), "w", encoding="utf-8", newline="\r\n") as f:
        f.write("".join(lines))
    print("wrote", name, len(T), "keys")
